//! The algorithm id every writer stamps on its rows (ADR 0104, ADR 0105).
//!
//! `algorithm/manifest.json` is generated by `cli algo manifest --write` from the constants it
//! names (the `algo` crate) and committed. Writers read it from here, compiled in with
//! `include_str!`, so no writer depends on the `algo` crate (which depends on `ai` and
//! `profile`). The `algo` crate's tests fail when the committed file no longer matches the code.

/// The committed manifest, as written (pretty JSON with sorted keys).
pub const MANIFEST_JSON: &str = include_str!("../../../../algorithm/manifest.json");

/// The `id` field of a manifest written by `cli algo manifest --write`: the top-level line
/// `  "id": "algo-…",`. `None` when the text has no such line.
pub fn id_of(manifest: &str) -> Option<&str> {
    manifest.lines().find_map(|l| {
        l.strip_prefix("  \"id\": \"")
            .and_then(|r| r.split('"').next())
            .filter(|id| id.starts_with("algo-"))
    })
}

/// This build's algorithm id, for example `algo-1.0.0+3f9c2a1b7d4e`.
pub fn id() -> &'static str {
    // The file is generated by our own writer; the `algo` crate's tests pin its shape.
    id_of(MANIFEST_JSON).unwrap_or("algo-unknown")
}

/// This build's manifest, as JSON text (bound as `$n::jsonb` by the writers).
pub fn manifest() -> &'static str {
    MANIFEST_JSON
}

/// `INSERT INTO algorithm_versions` for this build's id and manifest, as the first CTE of a
/// writer's statement: `{REGISTER_CTE_PREFIX}$a, $b::jsonb{REGISTER_CTE_SUFFIX} INSERT …`.
/// The row is written once (`ON CONFLICT DO NOTHING`), and the foreign key on the writer's
/// `algorithm_id` column is checked at the end of the statement, so it sees the new row.
pub fn register_cte(id_param: u32, manifest_param: u32) -> String {
    format!(
        "WITH algorithm_row AS (INSERT INTO algorithm_versions (id, manifest) \
         VALUES (${id_param}, ${manifest_param}::jsonb) ON CONFLICT (id) DO NOTHING) "
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_committed_manifest_has_an_id() {
        assert!(id().starts_with("algo-"), "{}", id());
        assert!(id().contains('+'), "{}", id());
        assert_ne!(id(), "algo-unknown");
    }

    #[test]
    fn id_of_reads_only_the_top_level_line() {
        let m = "{\n  \"components\": {\n    \"id\": \"algo-nested\"\n  },\n  \"id\": \"algo-1.2.3+abcdef012345\",\n  \"version\": \"1.2.3\"\n}\n";
        assert_eq!(id_of(m), Some("algo-1.2.3+abcdef012345"));
        assert_eq!(id_of("{}"), None);
    }

    #[test]
    fn the_register_cte_names_both_parameters() {
        let c = register_cte(9, 10);
        assert!(c.contains("VALUES ($9, $10::jsonb)"), "{c}");
        assert!(c.starts_with("WITH algorithm_row AS (INSERT INTO algorithm_versions"));
    }
}
